import maplibregl from 'maplibre-gl'; // Nhớ cài đặt maplibre-gl

export default {
  props: {
    selectedLocation: {
      type: Array,
      default: () => [105.85242472181584, 21.029579719995272]
    }
  },
  data() {
    return {
      map: null,
      apiUrl: 'https://rsapi.goong.io',
      mapUrl: 'https://tiles.goong.io/assets/',
      apiKey: 'ArPlUISaEBAdJFTABi9dcNGcue8WQ4cOAuGcNoBE',
      // your API key
      mapKey: 'tLyW2vk0aY3yfQLu8ZPy986mAgaW8igMYufv3BLY',
      // your map key
      center: [105.85242472181584, 21.029579719995272],
      // Kinh độ, vĩ độ
      zoom: 14 // Độ zoom mặc định
    };
  },
  mounted() {
    this.initMap();
  },
  watch: {
    selectedLocation: 'moveToLocation' // Theo dõi thay đổi tọa độ
  },
  methods: {
    initMap() {
      this.map = new maplibregl.Map({
        container: 'map',
        style: `${this.mapUrl}goong_map_web.json?api_key=${this.mapKey}`,
        center: this.selectedLocation,
        zoom: 14
      });
      this.map.on('load', () => {
        this.addMarkerAndCircleAround(this.selectedLocation);
      });
    },
    moveToLocation(newLocation) {
      this.map.flyTo({
        center: newLocation,
        essential: true
      });
      this.addMarkerAndCircleAround(newLocation);
    },
    removeLayer(layerId) {
      if (this.map.getLayer(layerId)) {
        this.map.removeLayer(layerId);
      }
    },
    addMarker(lngLat) {
      new maplibregl.Marker().setLngLat(lngLat).addTo(this.map);
    },
    addMarkerAndCircleAround(lngLat) {
      console.log(lngLat); // In ra tọa độ để kiểm tra

      // Thêm marker tại vị trí mới
      this.addMarker(lngLat);

      // Xóa vòng tròn cũ nếu có
      this.removeLayer('circle');

      // Tạo dữ liệu cho vòng tròn
      const circleData = {
        'type': 'FeatureCollection',
        'features': [{
          'type': 'Feature',
          'geometry': {
            'type': 'Polygon',
            'coordinates': [this.drawCircle(lngLat, this.radiusInMeters)]
          }
        }]
      };

      // Kiểm tra xem nguồn đã tồn tại chưa trước khi thêm
      if (this.map.getSource('circle')) {
        this.map.removeSource('circle');
      }

      // Thêm source cho vòng tròn
      this.map.addSource('circle', {
        'type': 'geojson',
        'data': circleData
      });

      // Thêm layer cho vòng tròn
      this.map.addLayer({
        'id': 'circle',
        'type': 'fill',
        'source': 'circle',
        'layout': {},
        'paint': {
          'fill-color': '#588888',
          'fill-opacity': 0.5
        }
      });

      // Di chuyển đến vị trí mới
      this.map.flyTo({
        center: lngLat,
        zoom: 14
      }); // Bạn có thể điều chỉnh zoom ở đây
    },
    drawCircle(center, radius) {
      const points = 64; // Số điểm để vẽ vòng tròn
      const coords = [];
      for (let i = 0; i < points; i++) {
        const angle = i / points * 2 * Math.PI;
        const dx = radius * Math.cos(angle);
        const dy = radius * Math.sin(angle);
        coords.push([center[0] + dx, center[1] + dy]);
      }
      coords.push(coords[0]); // Đảm bảo vòng tròn khép kín

      return coords;
    }
  }
};
